// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// Font Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// Gradient Constants matching the reference image
const PURPLE_GRADIENT = "linear-gradient(90deg, #E0C3FC 0%, #8EC5FC 100%)";
const PINK_GRADIENT = "linear-gradient(90deg, #ffdde1 0%, #ee9ca7 100%)";
const GLOW_PURPLE = "0 0 20px rgba(142, 197, 252, 0.4)";
const GLOW_PINK = "0 0 20px rgba(238, 156, 167, 0.4)";



export type DashboardProgressProps = Record<string, any>;

const ProgressBarRow: React.FC<{
  label: string;
  valueText: string;
  currentValue: number;
  maxValue: number;
  gradient: string;
  glow: string;
  delay: number;
  width: number;
  frame: number;
  fps: number;
}> = ({ label, valueText, currentValue, maxValue, gradient, glow, delay, width, frame, fps }) => {
  
  // Calculate percentage (clamped 0-100)
  const percentage = Math.min(100, Math.max(0, (currentValue / maxValue) * 100));
  
  // Animate opacity for stagger effect
  const opacity = interpolate(frame, [delay, delay + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const translateY = interpolate(frame, [delay, delay + 20], [20, 0], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: width * 0.015,
        opacity,
        transform: `translateY(${translateY}px)`,
        width: "100%",
        marginBottom: width * 0.04,
      }}
    >
      {/* Label Row */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "baseline",
          gap: width * 0.01,
          color: "white",
          fontSize: width * 0.035,
          fontFamily: "Inter",
          fontWeight: 700,
          textShadow: "0 2px 4px rgba(0,0,0,0.5)",
        }}
      >
        <span>{label}</span>
        {valueText && <span style={{ fontWeight: 600 }}>: {valueText}</span>}
      </div>

      {/* Progress Bar Track */}
      <div
        style={{
          width: "100%",
          height: width * 0.03, // Responsive height
          backgroundColor: "rgba(255, 255, 255, 0.1)",
          borderRadius: width * 0.015,
          overflow: "hidden",
          position: "relative",
          boxShadow: "inset 0 2px 4px rgba(0,0,0,0.3)",
        }}
      >
        {/* Progress Bar Fill */}
        <div
          style={{
            height: "100%",
            width: `${percentage}%`,
            background: gradient,
            borderRadius: width * 0.015,
            boxShadow: glow,
            position: "relative",
            transition: "none", // Critical for frame-based anim
          }}
        >
          {/* Shine effect */}
          <div
             style={{
               position: "absolute",
               top: 0,
               left: 0,
               width: "100%",
               height: "50%",
               background: "linear-gradient(180deg, rgba(255,255,255,0.4) 0%, rgba(255,255,255,0) 100%)",
               borderRadius: width * 0.015,
             }}
          />
        </div>
      </div>
    </div>
  );
};

const DashboardProgress: React.FC<DashboardProgressProps> = ({
  backgroundColor = "#08000f",
  transparentBackground = false,
  durationInSeconds = 5,
  
  budgetLabel = "Budget",
  budgetValueText = "$500/day",
  budgetStartVal = 0,
  budgetEndVal = 500,
  budgetMaxVal = 1000,

  cpaLabel = "CPA (Cost Per Action)",
  cpaValueText = "$56",
  cpaStartVal = 0,
  cpaEndVal = 56,
  cpaMaxVal = 100,

  roasLabel = "ROAS",
  roasValueText = "x1.6",
  roasStartVal = 3.0,
  roasEndVal = 1.6,
  roasMaxVal = 5.0,

  perfLabel = "Performance",
  perfValueText = "",
  perfStartVal = 100,
  perfEndVal = 75,
  perfMaxVal = 100,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Calculate size relative to the smallest dimension to ensure it fits in a 1:1 square center
  const size = Math.min(width, height);
  
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Animation timing
  const animDuration = (durationInSeconds - 1) * fps; // Leave 1s static at end
  
  const interpolateValue = (start: number, end: number, delayFrames: number) => {
    return interpolate(frame, [delayFrames, delayFrames + animDuration], [start, end], {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  };

  // Stagger delays
  const delayStep = 10;
  
  const currentBudget = interpolateValue(budgetStartVal, budgetEndVal, 0);
  const currentCPA = interpolateValue(cpaStartVal, cpaEndVal, delayStep);
  const currentROAS = interpolateValue(roasStartVal, roasEndVal, delayStep * 2);
  const currentPerf = interpolateValue(perfStartVal, perfEndVal, delayStep * 3);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
        padding: size * 0.05,
      }}
    >
      <div style={{ width: size * 0.9, maxWidth: 1200, display: "flex", flexDirection: "column" }}>
        
        <ProgressBarRow 
          label={budgetLabel}
          valueText={budgetValueText}
          currentValue={currentBudget}
          maxValue={budgetMaxVal}
          gradient={PURPLE_GRADIENT}
          glow={GLOW_PURPLE}
          delay={0}
          width={size}
          frame={frame}
          fps={fps}
        />

        <ProgressBarRow 
          label={cpaLabel}
          valueText={cpaValueText}
          currentValue={currentCPA}
          maxValue={cpaMaxVal}
          gradient={PURPLE_GRADIENT}
          glow={GLOW_PURPLE}
          delay={delayStep}
          width={size}
          frame={frame}
          fps={fps}
        />

        <ProgressBarRow 
          label={roasLabel}
          valueText={roasValueText}
          currentValue={currentROAS}
          maxValue={roasMaxVal}
          gradient={PINK_GRADIENT}
          glow={GLOW_PINK}
          delay={delayStep * 2}
          width={size}
          frame={frame}
          fps={fps}
        />

        <ProgressBarRow 
          label={perfLabel}
          valueText={perfValueText}
          currentValue={currentPerf}
          maxValue={perfMaxVal}
          gradient={PINK_GRADIENT}
          glow={GLOW_PINK}
          delay={delayStep * 3}
          width={size}
          frame={frame}
          fps={fps}
        />

      </div>
    </AbsoluteFill>
  );
};

export default DashboardProgress;